mapper.select:
SELECT status, COUNT(*) AS cnt
FROM attendance
WHERE tenant_id = #{tenantId}
  AND date BETWEEN #{weekStart} AND #{weekEnd}
GROUP BY status

SELECT AVG(work_hours)
FROM attendance
WHERE tenant_id = #{tenantId}
  AND date BETWEEN #{weekStart} AND #{weekEnd}
  AND work_hours IS NOT NULL

SELECT COUNT(DISTINCT employee_id)
FROM attendance
WHERE tenant_id = #{tenantId}
  AND date BETWEEN #{weekStart} AND #{weekEnd}

SELECT a.*
FROM attendance a
INNER JOIN (
    SELECT employee_id, date, MAX(update_time) AS max_update
    FROM attendance
    WHERE employee_id = #{employeeId}
      AND tenant_id = #{tenantId}
      AND date BETWEEN #{monthStart} AND #{monthEnd}
    GROUP BY employee_id, date
) latest ON a.employee_id = latest.employee_id
         AND a.date = latest.date
         AND a.update_time = latest.max_update
ORDER BY a.date ASC

SELECT *
FROM attendance
WHERE tenant_id = #{tenantId}
  AND date = #{date}
ORDER BY employee_id ASC

SELECT *
FROM attendance
WHERE tenant_id = #{tenantId}
  AND date BETWEEN #{weekStart} AND #{weekEnd}
  AND status IN (0, 2, 3)
ORDER BY date DESC, employee_id ASC
